export const RELAP5_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/relap5-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getRelap5StdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(RELAP5_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
